mapper.select:
SELECT e.*,d.MONITOR_ENV,d.MONITOR_GROUP,d.DOCKER_SUMMARY,d.IS_ONLINE
FROM MONITOR_DOCKER_EVENT e
LEFT JOIN MONITOR_DOCKER d ON e.SERVER_IP = d.SERVER_IP


        AND e.EVENT_ID = #{params.eventId}


        AND e.SERVER_IP LIKE CONCAT('%', #{params.serverIp}, '%')


        AND e.EVENT_STATUS LIKE CONCAT('%', #{params.eventStatus}, '%')


        AND e.EVENT_FROM LIKE CONCAT('%', #{params.eventFrom}, '%')


        AND e.EVENT_TYPE LIKE CONCAT('%', #{params.eventType}, '%')


        AND e.EVENT_ACTION LIKE CONCAT('%', #{params.eventAction}, '%')


        AND DATE_FORMAT(e.HAPPEN_TIME, '%Y-%m-%d') = #{params.happenTime}


        AND d.MONITOR_ENV = #{params.monitorEnv}


        AND d.MONITOR_GROUP = #{params.monitorGroup}


ORDER BY e.HAPPEN_TIME DESC,e.ID DESC

SELECT e.*,d.MONITOR_ENV,d.MONITOR_GROUP,d.DOCKER_SUMMARY,d.IS_ONLINE
FROM MONITOR_DOCKER_EVENT e
LEFT JOIN MONITOR_DOCKER d ON e.SERVER_IP = d.SERVER_IP


        AND e.SERVER_IP = #{serverIp}


        AND e.ID = #{id}
